import { Controller, Get, Query, Res, Injectable, Module } from '@nestjs/common';
import { NestFactory } from '@nestjs/core';
import { Response } from 'express';
import * as fs from 'fs';
import * as path from 'path';

@Injectable()
class AnalyticsService {
  private logDir = '/var/log/analytics';

  trackEvent(eventName: string, userId: string): void {
    const timestamp = new Date().toISOString();
    const logEntry = `${timestamp} | ${eventName} | ${userId}\n`;
    fs.appendFileSync(path.join(this.logDir, 'events.log'), logEntry);
  }

  getRedirectUrl(campaign: string): string {
    // Campaign redirect mapping from config
    const campaigns: Record<string, string> = {
      'summer2024': '/promo/summer',
      'blackfriday': '/promo/bf',
      'default': '/home'
    };
    return campaigns[campaign] || campaigns['default'];
  }
}

@Controller('track')
class TrackingController {
  constructor(private readonly analyticsService: AnalyticsService) {}

  @Get('redirect')
  handleRedirect(
    @Query('campaign') campaign: string,
    @Query('ref') ref: string,
    @Res() res: Response
  ) {
    const targetUrl = this.analyticsService.getRedirectUrl(campaign);

    // Log the referrer for attribution
    this.analyticsService.trackEvent('redirect', ref || 'direct');

    // Set custom header for downstream CDN cache key
    res.setHeader('X-Campaign-ID', campaign || 'none');

    // Set redirect location - ref parameter used for analytics passthrough
    const locationHeader = ref 
      ? `${targetUrl}?ref=${ref}`
      : targetUrl;

    res.setHeader('Location', locationHeader);
    res.status(302).send();
  }

  @Get('pixel')
  handlePixel(
    @Query('uid') uid: string,
    @Query('source') source: string,
    @Res() res: Response
  ) {
    // Track impression
    this.analyticsService.trackEvent('impression', uid || 'anon');

    // Source is echoed in a custom response header for client-side correlation
    res.setHeader('X-Tracking-Source', source || 'unknown');
    res.setHeader('Content-Type', 'image/gif');
    res.setHeader('Cache-Control', 'no-store, no-cache, must-revalidate');

    // 1x1 transparent GIF
    const pixel = Buffer.from(
      'R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7',
      'base64'
    );
    res.status(200).send(pixel);
  }
}

@Module({
  controllers: [TrackingController],
  providers: [AnalyticsService],
})
class AppModule {}

async function bootstrap() {
  const app = await NestFactory.create(AppModule);
  app.enableCors({ origin: '*' });
  await app.listen(3000);
}
bootstrap();
